	@Test
	void silentIsolatedCallerClosesExhaustedProviderOnceDuringConcurrentClose() throws Exception {
		var reading = new CountDownLatch(1);
		var finishRead = new CountDownLatch(1);
		@SuppressWarnings("unchecked")
		CloseableIteration<BindingSet> response = mock(CloseableIteration.class);
		when(response.hasNext()).thenAnswer(invocation -> {
			reading.countDown();
			assertThat(finishRead.await(10, TimeUnit.SECONDS)).isTrue();
			return false;
		});
		var provider = new RepositoryFederatedService(mock(Repository.class), false) {
			@Override
			public CloseableIteration<BindingSet> evaluate(Service service, CloseableIteration<BindingSet> inputs,
					String baseURI) {
				try (inputs) {
					inputs.next();
				}
				return response;
			}
		};
		var caller = new ListBindingSet(List.of("s", "unbound"), SimpleValueFactory.getInstance().createIRI("urn:s"),
				null);
		try (var executor = Executors.newFixedThreadPool(2,
				Thread.ofPlatform().name("service-close-race-", 0).factory());
				var output = silentScheduledService(List.of(caller), provider)) {
			var read = executor.submit(output::hasNext);
			try {
				assertThat(reading.await(10, TimeUnit.SECONDS)).isTrue();
				var close = executor.submit(() -> {
					finishRead.countDown();
					output.close();
				});
				assertThat(read.get(10, TimeUnit.SECONDS)).isFalse();
				close.get(10, TimeUnit.SECONDS);
				verify(response, times(1)).close();
			} finally {
				finishRead.countDown();
			}
		}
	}

	private static ServiceJoinIterator silentScheduledService(List<BindingSet> callers, boolean lazy,
			UnaryOperator<BindingSet> resultFor) {
		var provider = new RepositoryFederatedService(mock(Repository.class), false) {
			@Override
			public CloseableIteration<BindingSet> evaluate(Service service, CloseableIteration<BindingSet> inputs,
					String baseURI) {
				var output = new ConvertingIteration<BindingSet, BindingSet>(inputs) {
					@Override
					protected BindingSet convert(BindingSet input) {
						return resultFor.apply(input);
					}
				};
				return lazy ? output : new CloseableIteratorIteration<>(Iterations.asList(output).iterator());
			}
		};
		return silentScheduledService(callers, provider);
	}

	private static ServiceJoinIterator silentScheduledService(List<BindingSet> callers, FederatedService provider) {
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null, ignored -> provider);
		var service = service(QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { SERVICE SILENT <urn:endpoint> { ?s <urn:p> ?hit } }", null).getTupleExpr());
		return ServiceJoinIterator.forBoundJoinBatch(callers, service, strategy, new BlankNodeAllocationScope());
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void opaqueStreamingCallerIsReleasedBeforeTheNextRequest(boolean metadata) throws Exception {
		var first = new AtomicReference<WeakReference<Value>>();
		var vf = SimpleValueFactory.getInstance();
		var consumed = new AtomicInteger();
		var callers = IntStream.range(0, 1000).<BindingSet>mapToObj(index -> {
			var graph = vf.createIRI("urn:graph:" + index);
			first.compareAndSet(null, new WeakReference<>(graph));
			consumed.incrementAndGet();
			return metadata ? GraphFrameBindings.supply(new MapBindingSet(), "graph", graph)
					: new ListBindingSet(List.of("graph"), graph);
		}).iterator();
		var provider = new RepositoryFederatedService(mock(Repository.class), false) {
			@Override
			public CloseableIteration<BindingSet> select(Service service, Set<String> projection, BindingSet row,
					String baseURI) {
				assertThat(row.getBindingNames()).containsExactly("graph");
				return new SingletonIteration<>(row);
			}
		};
		try (var output = join(provider, new CloseableIteratorIteration<>(callers), EmptyBindingSet.getInstance(),
				false, "VALUES ?o { 1 }")) {
			for (int index = 0; index < 32; index++) {
				var row = output.next();
				assertThat(row.getValue("graph")).isEqualTo(vf.createIRI("urn:graph:" + index));
				assertThat(GraphFrameBindings.isSupplied(row, "graph")).isEqualTo(metadata);
			}
			assertThat(consumed.get()).isEqualTo(32);
			var queue = new ReferenceQueue<>();
			var witness = new WeakReference<>(new Object(), queue);
			System.gc();
			assertThat(queue.remove(10_000)).isSameAs(witness);
			assertThat(first.get().get()).as("completed callers are collectible before the cursor closes").isNull();
		}
	}

	@Test
	void scheduledOpaqueUuidInvocationKeepsReorderedPublicValues() {
		var vf = SimpleValueFactory.getInstance();
		var calls = new AtomicInteger();
		List<BindingSet> callers = List.of(new ListBindingSet(List.of("id"), vf.createLiteral(1)),
				new ListBindingSet(List.of("id"), vf.createLiteral(2)));
		var provider = new RepositoryFederatedService(mock(Repository.class), false) {
			@Override
			public CloseableIteration<BindingSet> evaluate(Service service, CloseableIteration<BindingSet> inputs,
					String baseURI) {
				calls.incrementAndGet();
				var uuid = vf.createIRI("urn:uuid:" + UUID.randomUUID());
				var output = new ArrayList<BindingSet>();
				for (var input : Iterations.asList(inputs)) {
					assertThat(input.getBindingNames()).containsExactly("id");
					output.addFirst(new ListBindingSet(List.of("id", "u"), input.getValue("id"), uuid));
				}
				return new CloseableIteratorIteration<>(output.iterator());
			}
		};
		var rows = scheduledRows(provider, callers, "BIND(UUID() AS ?u)");
		assertThat(calls.get()).isOne();
		assertThat(rows.stream().map(row -> row.getValue("u")).distinct().count()).isOne();
		assertThat(rows).extracting(row -> row.getValue("id"))
				.containsExactly(vf.createLiteral(2), vf.createLiteral(1));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void opaqueHookOwnsItsConsumptionOfScheduledOrdinaryCallers(boolean consumeAll) {
		var calls = new AtomicInteger();
		var provider = new RepositoryFederatedService(mock(Repository.class), false) {
			@Override
			public CloseableIteration<BindingSet> evaluate(Service service, CloseableIteration<BindingSet> inputs,
					String baseURI) {
				calls.incrementAndGet();
				try (inputs) {
					if (consumeAll) {
						return new CloseableIteratorIteration<>(Iterations.asList(inputs).iterator());
					}
					return new SingletonIteration<>(inputs.next());
				}
			}
		};
		var vf = SimpleValueFactory.getInstance();
		List<BindingSet> callers = IntStream.range(0, 3)
				.<BindingSet>mapToObj(index -> new ListBindingSet(List.of("id"), vf.createLiteral(index)))
				.toList();
		assertThat(scheduledRows(provider, callers, "VALUES ?o { 1 }"))
				.containsExactlyElementsOf(consumeAll ? callers : callers.subList(0, 1));
		assertThat(calls.get()).isOne();
	}

